<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Categorias - Achei Profissional</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><style>:root{--p:#0876d1;--ink:#263746;--muted:#71808e;--border:#dce6ee;--bg:#f5f8fb}body{margin:0;background:var(--bg);color:var(--ink);font-family:Arial,sans-serif;font-size:14px}.nav{background:#fff;border-bottom:1px solid var(--border)}.navin{max-width:1080px;margin:auto;padding:17px 20px;display:flex;justify-content:space-between;align-items:center}.brand{color:var(--p);font-weight:700;text-decoration:none}.nav a{color:#354454;text-decoration:none;margin-left:15px;font-size:13px}.page{max-width:920px;margin:auto;padding:35px 20px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.head h1{font-size:24px;margin:0}.back{color:var(--p);text-decoration:none}.layout{display:grid;grid-template-columns:300px 1fr;gap:18px}.card{background:#fff;border:1px solid var(--border);border-radius:13px;padding:21px;box-shadow:0 4px 14px #2346640d}.card h2{font-size:16px;margin:0 0 16px}.label{display:block;font-size:12px;font-weight:600;margin:13px 0 6px}.input{width:100%;box-sizing:border-box;border:1px solid #ccd9e3;border-radius:7px;padding:10px}.btn{width:100%;border:0;background:var(--p);color:#fff;border-radius:7px;padding:10px;margin-top:15px}.search{margin-bottom:14px}.table{width:100%;border-collapse:collapse}.table th,.table td{text-align:left;border-bottom:1px solid #edf1f4;padding:13px 8px;font-size:13px}.table th{color:var(--muted);font-size:11px;text-transform:uppercase}.badge{border-radius:20px;background:#e8f8ef;color:#23814e;padding:5px 9px;font-size:11px}.actions a{color:var(--p);margin-right:10px;font-size:12px}@media(max-width:700px){.layout{grid-template-columns:1fr}.head{align-items:flex-start;gap:12px;flex-direction:column}.table{display:block;overflow:auto;white-space:nowrap}}</style></head><body><header class="nav"><div class="navin"><a class="brand" href="<?= site_url('admin') ?>">Achei Profissional</a><div><a href="<?= site_url('admin') ?>">Administração</a><a href="<?= site_url('busca') ?>">Buscar</a></div></div></header><main class="page"><div class="head"><div><h1>Gerenciar categorias</h1><span style="color:var(--muted);font-size:13px">Categorias utilizadas nos filtros e nos perfis profissionais.</span></div><a class="back" href="<?= site_url('admin') ?>"><i class="bi bi-arrow-left"></i> Voltar ao painel</a></div><div class="layout"><section class="card"><h2>Nova categoria</h2><label class="label" for="nome">Nome da categoria</label><input class="input" id="nome" placeholder="Ex.: Jardinagem"><label class="label" for="descricao">Descrição</label><textarea class="input" id="descricao" rows="4" placeholder="Descreva o tipo de serviço"></textarea><button class="btn" type="button">Cadastrar categoria</button></section><section class="card"><input class="input search" placeholder="Pesquisar categoria"><table class="table"><thead><tr><th>Categoria</th><th>Profissionais</th><th>Status</th><th>Ações</th></tr></thead><tbody><tr><td>Eletricista</td><td>24</td><td><span class="badge">Ativa</span></td><td class="actions"><a href="#">Editar</a><a href="#">Excluir</a></td></tr><tr><td>Encanador</td><td>18</td><td><span class="badge">Ativa</span></td><td class="actions"><a href="#">Editar</a><a href="#">Excluir</a></td></tr><tr><td>Designer</td><td>12</td><td><span class="badge">Ativa</span></td><td class="actions"><a href="#">Editar</a><a href="#">Excluir</a></td></tr><tr><td>Fotógrafo</td><td>9</td><td><span class="badge">Ativa</span></td><td class="actions"><a href="#">Editar</a><a href="#">Excluir</a></td></tr></tbody></table></section></div></main></body></html>
